#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = malloc(4 * sizeof(int));
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        ptr[i] = i + 1;
    }

    for (int i = 0; i < 4; i++) {
        printf("%d ", ptr[i]);
    }

    free(ptr);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int *arr = malloc(5 * sizeof(int));
    if (arr == NULL) {
        return 1;
    }

    for (int i = 0; i < 5; i++) {
        arr[i] = i;
    }

    free(arr);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int *ptr = malloc(sizeof(int));
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    *ptr = 42;
    free(ptr);

    printf("%d\n", *ptr);
    return 0;
}

